package care.tend.item;
import jakarta.persistence.*; import java.time.*; import java.math.BigDecimal; import java.util.UUID;
@Entity @Table(name="life_item")
public class LifeItem { public enum Type{BRAIN_DUMP,GOAL,TASK,HABIT}
  @Id @GeneratedValue(strategy=GenerationType.UUID) public UUID id; @Column(name="user_id",nullable=false) public UUID userId; @Column(name="category_id") public UUID categoryId; @Enumerated(EnumType.STRING) @Column(nullable=false) public Type type;
  @Column(nullable=false) public String title; @Column(columnDefinition="text") public String description; @Column(nullable=false) public String status="ACTIVE"; public String priority; public String energy; @Column(name="due_date") public LocalDate dueDate; @Column(name="scheduled_date") public LocalDate scheduledDate; @Column(name="minimum_action") public String minimumAction; public String recurrence; @Column(name="parent_id") public UUID parentId; @Column(name="sort_order") public int sortOrder; public boolean processed; @Column(name="habit_type") public String habitType; public String unit; @Column(name="ideal_target") public BigDecimal idealTarget; @Column(name="minimum_target") public BigDecimal minimumTarget; @Column(name="selected_weekdays") public Short[] selectedWeekdays; @Column(name="target_per_week") public Short targetPerWeek; @Column(name="progress_model") public String progressModel; @Column(name="target_value") public BigDecimal targetValue; @Column(name="progress_value") public BigDecimal progressValue; @Column(name="completed_at") public Instant completedAt; @Column(name="created_at",insertable=false,updatable=false) public Instant createdAt; @Column(name="updated_at",insertable=false) public Instant updatedAt;
}
